     const g=markerGeometry(kinds[which],which==='start'?{x:coords.x1,y:coords.y1}:{x:coords.x2,y:coords.y2},which==='start'?{x:coords.x2,y:coords.y2}:{x:coords.x1,y:coords.y1});
